      "n": "LiquorAlba (Nocciolino Langhe)",
      "cat": "liquori",
      "reg": "Piemonte",
      "city": "La Morra (CN)",
      "lat": 44.638,
      "lng": 7.934,
      "y": null,
      "certs": [],
